app_css:
.tool-app-cashroute { color: #052e16; max-width: 900px; margin-inline: auto; font-family: inherit; }
.tool-app-cashroute .cr-hidden { display: none !important; }
.tool-app-cashroute .cr-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 14px; }
.tool-app-cashroute .cr-tab { background: #f0fdf4; border: 1px solid #bbf7d0; color: #166534; border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-cashroute .cr-tab:hover { background: #dcfce7; }
.tool-app-cashroute .cr-tab-active { background: #16A34A; border-color: #16A34A; color: #fff; }
.tool-app-cashroute .cr-pane h3 { font-size: 16px; margin: 18px 0 10px; }
.tool-app-cashroute .cr-card { background: #f8fdf9; border: 1px solid #bbf7d0; border-radius: 12px; padding: 16px; margin-bottom: 14px; }
.tool-app-cashroute .cr-card h3 { margin-top: 0; }
.tool-app-cashroute .cr-formgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 12px; }
.tool-app-cashroute label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; color: #14532d; }
.tool-app-cashroute input, .tool-app-cashroute select, .tool-app-cashroute textarea { border: 1px solid #86efac; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; color: #052e16; }
.tool-app-cashroute .cr-hint { font-size: 13px; color: #4d7c5f; margin: 6px 0; }
.tool-app-cashroute .cr-hint code { background: #eef7f0; padding: 2px 6px; border-radius: 4px; font-size: 12px; }
.tool-app-cashroute .cr-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.tool-app-cashroute .cr-btn { background: #16A34A; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-cashroute .cr-btn:hover { background: #15803d; }
.tool-app-cashroute .cr-btn-ghost { background: #e9fbef; color: #16A34A; border: 1px solid #bbf7d0; }
.tool-app-cashroute .cr-btn-ghost:hover { background: #dcfce7; }
.tool-app-cashroute table.cr-table { width: 100%; border-collapse: collapse; margin: 8px 0; font-size: 13px; }
.tool-app-cashroute table.cr-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: #166534; padding: 8px 6px; border-bottom: 2px solid #bbf7d0; white-space: nowrap; }
.tool-app-cashroute table.cr-table td { padding: 8px 6px; border-bottom: 1px solid #dcfce7; vertical-align: top; }
.tool-app-cashroute table.cr-table tr.cr-flagrow td { background: #fefce8; }
.tool-app-cashroute .cr-flag { display: inline-block; background: #fef9c3; border: 1px solid #facc15; color: #854d0e; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 700; margin: 2px 4px 2px 0; white-space: nowrap; }
.tool-app-cashroute .cr-okflag { display: inline-block; background: #dcfce7; color: #166534; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 700; }
.tool-app-cashroute .cr-stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; margin: 8px 0; }
.tool-app-cashroute .cr-stat { background: #fff; border: 1px solid #bbf7d0; border-radius: 12px; padding: 12px 14px; }
.tool-app-cashroute .cr-stat .cr-stat-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: #4d7c5f; }
.tool-app-cashroute .cr-stat .cr-stat-value { font-size: 22px; font-weight: 800; margin: 4px 0; }
.tool-app-cashroute .cr-stat .cr-stat-sub { font-size: 12px; color: #4d7c5f; }
.tool-app-cashroute .cr-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 16px; padding: 2px 6px; }
.tool-app-cashroute .cr-empty { color: #4d7c5f; font-size: 14px; padding: 12px 4px; }
.tool-app-cashroute .cr-badge-red { background: #fee2e2; color: #991b1b; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 800; }
.tool-app-cashroute .cr-badge-amber { background: #fef9c3; color: #854d0e; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 800; }
.tool-app-cashroute .cr-badge-green { background: #dcfce7; color: #166534; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 800; }
.tool-app-cashroute .tool-print-doc { display: none; }
@media print {
  .tool-app-cashroute .cr-tabs, .tool-app-cashroute .cr-card, .tool-app-cashroute .cr-pane .cr-card { display: none !important; }
  .tool-app-cashroute .tool-print-doc { display: block !important; color: #000; }
  .tool-app-cashroute .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-cashroute .tool-print-doc th, .tool-app-cashroute .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 12px; }
}

app_js:
(function () {
  'use strict';

  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) {
    n = parseFloat(n);
    if (!isFinite(n)) n = 0;
    var sign = n < 0 ? '-' : '';
    return sign + '$' + Math.abs(n).toFixed(2);
  }
  function todayStr() {
    var d = new Date();
    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);
  }
  function thisMonth() { return todayStr().slice(0, 7); }

  var LS = 'toolapp-cashroute-v1';
  function defaultState() { return { machines: [], statements: [], loads: [], outages: [] }; }
  function loadState() {
    try {
      var s = JSON.parse(localStorage.getItem(LS));
      if (s && Array.isArray(s.machines)) return s;
    } catch (e) {}
    return defaultState();
  }
  var state = loadState();
  function save() { try { localStorage.setItem(LS, JSON.stringify(state)); } catch (e) {} }
  function machineIds() { return state.machines.map(function (m) { return m.id; }); }
  function findMachine(id) {
    for (var i = 0; i < state.machines.length; i++) {
      if (state.machines[i].id === id) return state.machines[i];
    }
    return null;
  }

  /* ---------------- tabs ---------------- */
  function showTab(name) {
    var tabs = document.querySelectorAll('.tool-app-cashroute .cr-tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].classList.toggle('cr-tab-active', tabs[i].getAttribute('data-cr-tab') === name);
    }
    var panes = document.querySelectorAll('.tool-app-cashroute .cr-pane');
    for (var j = 0; j < panes.length; j++) {
      panes[j].classList.toggle('cr-hidden', panes[j].id !== 'cr-pane-' + name);
    }
    render();
  }

  /* ---------------- machines ---------------- */
  function addMachine() {
    var id = ($('cr-m-id').value || '').trim();
    if (!id) { alert('Enter a machine ID.'); return; }
    if (machineIds().indexOf(id) !== -1) { alert('That machine ID is already registered.'); return; }
    state.machines.push({
      id: id,
      loc: ($('cr-m-loc').value || '').trim(),
      surcharge: parseFloat($('cr-m-surch').value) || 0,
      cash: parseFloat($('cr-m-cash').value) || 0
    });
    save();
    $('cr-m-id').value = '';
    $('cr-m-loc').value = '';
    render();
  }
  function removeMachine(id) {
    if (!confirm('Remove ' + id + ' and all of its history?')) return;
    state.machines = state.machines.filter(function (m) { return m.id !== id; });
    state.statements = state.statements.filter(function (s) { return s.machine !== id; });
    state.loads = state.loads.filter(function (l) { return l.machine !== id; });
    state.outages = state.outages.filter(function (o) { return o.machine !== id; });
    save();
    render();
  }

  /* ---------------- statements ---------------- */
  function parseCSV(text) {
    var lines = text.split(/\r?\n/);
    var rows = [];
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (!line) continue;
      if (i === 0 && line.toLowerCase().indexOf('date') === 0) continue;
      var parts = line.split(',');
      if (parts.length < 6) continue;
      rows.push({
        date: parts[0].trim(),
        machine: parts[1].trim(),
        txns: parseInt(parts[2], 10) || 0,
        surcharge: parseFloat(parts[3]) || 0,
        interchange: parseFloat(parts[4]) || 0,
        fees: parseFloat(parts[5]) || 0
      });
    }
    return rows;
  }
  function importText(text) {
    var rows = parseCSV(text);
    if (!rows.length) {
      alert('No data rows found. Expected columns: date,machine,transactions,surcharge,interchange,fees');
      return;
    }
    state.statements = state.statements.concat(rows);
    save();
    render();
  }
  function flagsFor(row, priorAvg) {
    var flags = [];
    var gross = row.surcharge + row.interchange;
    if (machineIds().indexOf(row.machine) === -1) flags.push('Unknown machine');
    if (gross > 0 && row.fees / gross > 0.15) {
      flags.push('High fees — ' + (100 * row.fees / gross).toFixed(1) + '% of gross');
    }
    if (priorAvg && priorAvg > 0 && Math.abs(row.txns - priorAvg) / priorAvg > 0.4) {
      flags.push('Volume swing vs. recent average');
    }
    if (row.txns === 0) flags.push('Zero transactions');
    return flags;
  }
  function flaggedStatements() {
    var byMachine = {};
    var out = [];
    var sorted = state.statements.slice().sort(function (a, b) {
      return a.date < b.date ? -1 : (a.date > b.date ? 1 : 0);
    });
    for (var i = 0; i < sorted.length; i++) {
      var r = sorted[i];
      var prev = byMachine[r.machine] || [];
      var avg = prev.length ? prev.reduce(function (a, b) { return a + b; }, 0) / prev.length : null;
      out.unshift({ row: r, flags: flagsFor(r, avg) });
      prev.push(r.txns);
      if (prev.length > 3) prev.shift();
      byMachine[r.machine] = prev;
    }
    return out;
  }

  /* ---------------- cash ---------------- */
  function logLoad() {
    var id = $('cr-c-mach').value;
    if (!id) { alert('Register a machine first.'); return; }
    var m = findMachine(id);
    var disp = parseFloat($('cr-c-disp').value) || 0;
    var amt = parseFloat($('cr-c-amt').value) || 0;
    m.cash = Math.max(0, (m.cash || 0) - disp) + amt;
    state.loads.push({
      machine: id,
      date: $('cr-c-date').value || todayStr(),
      amount: amt,
      dispensed: disp
    });
    save();
    $('cr-c-disp').value = 0;
    render();
  }
  function forecastFor(m) {
    var loads = state.loads.filter(function (l) { return l.machine === m.id; })
      .sort(function (a, b) { return a.date < b.date ? -1 : 1; });
    if (!loads.length) return { m: m, days: null, cls: '', note: 'No load history yet' };
    var spanDays = (Date.parse(loads[loads.length - 1].date) - Date.parse(loads[0].date)) / 86400000;
    if (!isFinite(spanDays) || spanDays < 1) spanDays = 1;
    var total = 0, i;
    for (i = 0; i < loads.length; i++) total += loads[i].dispensed;
    var daily = total / spanDays;
    if (!daily || daily <= 0) return { m: m, days: null, cls: '', note: 'No dispense history yet' };
    var days = (m.cash || 0) / daily;
    var cls = days <= 2 ? 'cr-badge-red' : (days <= 7 ? 'cr-badge-amber' : 'cr-badge-green');
    var note = days <= 2 ? 'Refill now' : (days <= 7 ? 'Refill soon' : 'Healthy');
    return { m: m, days: days, cls: cls, note: note, daily: daily };
  }

  /* ---------------- uptime ---------------- */
  function logOutage() {
    var id = $('cr-u-mach').value;
    if (!id) { alert('Register a machine first.'); return; }
    var start = $('cr-u-start').value;
    var end = $('cr-u-end').value;
    if (!start || !end || new Date(end) <= new Date(start)) {
      alert('Enter a valid start and end time.');
      return;
    }
    state.outages.push({
      machine: id,
      start: start,
      end: end,
      reason: ($('cr-u-reason').value || '').trim()
    });
    save();
    $('cr-u-reason').value = '';
    render();
  }
  function uptimeFor(m) {
    var now = new Date();
    var windowStart = new Date(now.getTime() - 30 * 86400000);
    var windowMins = 30 * 24 * 60;
    var downMins = 0;
    for (var i = 0; i < state.outages.length; i++) {
      var o = state.outages[i];
      if (o.machine !== m.id) continue;
      var s = new Date(o.start), e = new Date(o.end);
      if (isNaN(s.getTime()) || isNaN(e.getTime()) || e <= s) continue;
      var os = s < windowStart ? windowStart : s;
      var oe = e > now ? now : e;
      if (oe > os) downMins += (oe - os) / 60000;
    }
    var up = Math.max(0, (windowMins - downMins) / windowMins * 100);
    return { m: m, uptime: up, downMins: downMins };
  }

  /* ---------------- report ---------------- */
  function reportFor(month) {
    var agg = {};
    var machinesSeen = {};
    for (var i = 0; i < state.statements.length; i++) {
      var r = state.statements[i];
      if (r.date.slice(0, 7) !== month) continue;
      if (!agg[r.machine]) agg[r.machine] = { txns: 0, surcharge: 0, interchange: 0, fees: 0 };
      var a = agg[r.machine];
      a.txns += r.txns;
      a.surcharge += r.surcharge;
      a.interchange += r.interchange;
      a.fees += r.fees;
      machinesSeen[r.machine] = true;
    }
    var ids = Object.keys(agg);
    var total = { txns: 0, surcharge: 0, interchange: 0, fees: 0 };
    for (var j = 0; j < ids.length; j++) {
      total.txns += agg[ids[j]].txns;
      total.surcharge += agg[ids[j]].surcharge;
      total.interchange += agg[ids[j]].interchange;
      total.fees += agg[ids[j]].fees;
    }
    return { per: agg, total: total };
  }
  function printReport() {
    var month = $('cr-r-month').value || thisMonth();
    var rep = reportFor(month);
    var ids = Object.keys(rep.per);
    var html = '<h1>CashRoute route report — ' + esc(month) + '</h1>';
    if (!ids.length) {
      html += '<p>No statement data for this month.</p>';
    } else {
      html += '<table><thead><tr><th>Machine</th><th>Txns</th><th>Surcharge</th>' +
        '<th>Interchange</th><th>Fees</th><th>Net</th></tr></thead><tbody>';
      for (var i = 0; i < ids.length; i++) {
        var a = rep.per[ids[i]];
        var net = a.surcharge + a.interchange - a.fees;
        html += '<tr><td>' + esc(ids[i]) + '</td><td>' + a.txns + '</td><td>' + money(a.surcharge) +
          '</td><td>' + money(a.interchange) + '</td><td>' + money(a.fees) + '</td><td>' + money(net) + '</td></tr>';
      }
      var t = rep.total;
      html += '</tbody><tfoot><tr><th>Total</th><th>' + t.txns + '</th><th>' + money(t.surcharge) +
        '</th><th>' + money(t.interchange) + '</th><th>' + money(t.fees) + '</th><th>' +
        money(t.surcharge + t.interchange - t.fees) + '</th></tr></tfoot></table>';
    }
    $('cr-printdoc').innerHTML = html;
    window.print();
  }

  /* ---------------- demo data ---------------- */
  function loadDemo() {
    state = defaultState();
    state.machines = [
      { id: 'ATM-001', loc: 'Downtown Liquor', surcharge: 3.00, cash: 2400 },
      { id: 'ATM-002', loc: 'Main St Market', surcharge: 2.50, cash: 900 },
      { id: 'ATM-003', loc: 'Airport Plaza', surcharge: 4.00, cash: 5200 }
    ];
    var stmt = [
      ['2026-08-01', 'ATM-001', 118, 354.00, 44.84, 38.20],
      ['2026-08-01', 'ATM-002', 203, 507.50, 77.14, 61.10],
      ['2026-08-01', 'ATM-003', 96, 384.00, 36.48, 34.55],
      ['2026-09-01', 'ATM-001', 121, 363.00, 45.98, 39.40],
      ['2026-09-01', 'ATM-002', 199, 497.50, 75.62, 59.80],
      ['2026-09-01', 'ATM-003', 101, 404.00, 38.38, 36.10],
      ['2026-10-01', 'ATM-001', 117, 351.00, 44.46, 37.90],
      ['2026-10-01', 'ATM-002', 62, 155.00, 23.56, 88.40],
      ['2026-10-01', 'ATM-003', 98, 392.00, 37.24, 35.20]
    ];
    for (var i = 0; i < stmt.length; i++) {
      state.statements.push({
        date: stmt[i][0], machine: stmt[i][1], txns: stmt[i][2],
        surcharge: stmt[i][3], interchange: stmt[i][4], fees: stmt[i][5]
      });
    }
    state.loads = [
      { machine: 'ATM-001', date: '2026-09-20', amount: 3000, dispensed: 0 },
      { machine: 'ATM-001', date: '2026-10-05', amount: 2500, dispensed: 2900 },
      { machine: 'ATM-002', date: '2026-09-28', amount: 2000, dispensed: 0 },
      { machine: 'ATM-002', date: '2026-10-11', amount: 1200, dispensed: 2300 },
      { machine: 'ATM-003', date: '2026-10-02', amount: 3000, dispensed: 1800 }
    ];
    var oStart = new Date(Date.now() - 6 * 86400000);
    var oEnd = new Date(Date.now() - 6 * 86400000 + 5 * 3600000);
    state.outages = [
      {
        machine: 'ATM-002', start: oStart.toISOString().slice(0, 16),
        end: oEnd.toISOString().slice(0, 16), reason: 'Card reader fault'
      }
    ];
    save();
    render();
  }
  function clearAll() {
    if (!confirm('Delete all machines, statements, loads, and outages?')) return;
    state = defaultState();
    save();
    render();
  }

  /* ---------------- render ---------------- */
  function render() {
    renderMachines();
    renderStatements();
    renderCash();
    renderUptime();
    renderReport();
  }
  function renderMachines() {
    var el = $('cr-m-list');
    if (!state.machines.length) {
      el.innerHTML = '<p class="cr-empty">No machines yet. Register your first machine above.</p>';
      return;
    }
    var h = '<table class="cr-table"><thead><tr><th>Machine</th><th>Location</th>' +
      '<th>Surcharge</th><th>Cash on hand</th><th>Forecast</th><th></th></tr></thead><tbody>';
    for (var i = 0; i < state.machines.length; i++) {
      var m = state.machines[i];
      var f = forecastFor(m);
      var fc = f.days === null
        ? '<span class="cr-okflag">—</span>'
        : '<span class="' + f.cls + '">' + f.days.toFixed(1) + ' days · ' + esc(f.note) + '</span>';
      h += '<tr><td><strong>' + esc(m.id) + '</strong></td><td>' + esc(m.loc || '—') + '</td>' +
        '<td>' + money(m.surcharge) + '</td><td>' + money(m.cash) + '</td><td>' + fc + '</td>' +
        '<td><button type="button" class="cr-del" data-cr-delmach="' + esc(m.id) + '" aria-label="Remove machine">×</button></td></tr>';
    }
    el.innerHTML = h + '</tbody></table>';
  }
  function renderStatements() {
    var flagged = flaggedStatements();
    var nFlags = 0;
    for (var i = 0; i < flagged.length; i++) nFlags += flagged[i].flags.length;
    var fe = $('cr-s-flags');
    if (!flagged.length) {
      fe.innerHTML = '';
    } else if (nFlags) {
      fe.innerHTML = '<div class="cr-card"><h3>' + nFlags + ' flag' + (nFlags === 1 ? '' : 's') + ' found</h3>' +
        '<p class="cr-hint">Fee lines taking more than 15% of gross, unregistered machines, volume swings over 40%, and zero-transaction periods are flagged for review.</p></div>';
    } else {
      fe.innerHTML = '<p class="cr-empty"><span class="cr-okflag">Clean</span> — no fee anomalies in the imported statements.</p>';
    }
    var el = $('cr-s-list');
    if (!flagged.length) {
      el.innerHTML = '<p class="cr-empty">Import a processor statement CSV to see transactions and fee flags.</p>';
      return;
    }
    var h = '<table class="cr-table"><thead><tr><th>Date</th><th>Machine</th><th>Txns</th>' +
      '<th>Surcharge</th><th>Interchange</th><th>Fees</th><th>Net</th><th>Flags</th></tr></thead><tbody>';
    for (var j = 0; j < flagged.length; j++) {
      var r = flagged[j].row;
      var net = r.surcharge + r.interchange - r.fees;
      var fl = '';
      for (var k = 0; k < flagged[j].flags.length; k++) {
        fl += '<span class="cr-flag">' + esc(flagged[j].flags[k]) + '</span>';
      }
      h += '<tr' + (flagged[j].flags.length ? ' class="cr-flagrow"' : '') + '><td>' + esc(r.date) +
        '</td><td><strong>' + esc(r.machine) + '</strong></td><td>' + r.txns + '</td><td>' + money(r.surcharge) +
        '</td><td>' + money(r.interchange) + '</td><td>' + money(r.fees) + '</td><td>' + money(net) +
        '</td><td>' + (fl || '<span class="cr-okflag">OK</span>') + '</td></tr>';
    }
    el.innerHTML = h + '</tbody></table>';
  }
  function syncMachineSelect(sel, keep) {
    var el = $(sel);
    var val = keep || el.value;
    var h = '';
    for (var i = 0; i < state.machines.length; i++) {
      h += '<option value="' + esc(state.machines[i].id) + '"' +
        (state.machines[i].id === val ? ' selected' : '') + '>' +
        esc(state.machines[i].id) + ' — ' + esc(state.machines[i].loc || 'no location') + '</option>';
    }
    el.innerHTML = h;
  }
  function renderCash() {
    syncMachineSelect('cr-c-mach');
    var fc = forecastFor.length ? '' : '';
    var h = '<div class="cr-stat-grid">';
    if (!state.machines.length) {
      h += '</div><p class="cr-empty">Register a machine to start forecasting refills.</p>';
    } else {
      for (var i = 0; i < state.machines.length; i++) {
        var f = forecastFor(state.machines[i]);
        var val = f.days === null ? '—' : f.days.toFixed(1) + ' days';
        var sub = f.days === null ? f.note : 'avg ' + money(f.daily) + '/day';
        h += '<div class="cr-stat"><div class="cr-stat-label">' + esc(f.m.id) + '</div>' +
          '<div class="cr-stat-value">' + val + '</div>' +
          '<div class="cr-stat-sub">' + esc(sub) + (f.days !== null ? ' · <span class="' + f.cls + '">' + esc(f.note) + '</span>' : '') + '</div></div>';
      }
      h += '</div>';
    }
    $('cr-c-forecast').innerHTML = h;
    var el = $('cr-c-list');
    var loads = state.loads.slice().sort(function (a, b) { return a.date < b.date ? -1 : 1; });
    if (!loads.length) {
      el.innerHTML = '<p class="cr-empty">No loads logged yet.</p>';
      return;
    }
    var t = '<table class="cr-table"><thead><tr><th>Date</th><th>Machine</th><th>Loaded</th><th>Dispensed</th></tr></thead><tbody>';
    for (var j = 0; j < loads.length; j++) {
      t += '<tr><td>' + esc(loads[j].date) + '</td><td><strong>' + esc(loads[j].machine) +
        '</strong></td><td>' + money(loads[j].amount) + '</td><td>' + money(loads[j].dispensed) + '</td></tr>';
    }
    el.innerHTML = t + '</tbody></table>';
  }
  function renderUptime() {
    syncMachineSelect('cr-u-mach');
    var h = '<div class="cr-stat-grid">';
    if (!state.machines.length) {
      h += '</div><p class="cr-empty">Register a machine to track uptime.</p>';
    } else {
      for (var i = 0; i < state.machines.length; i++) {
        var u = uptimeFor(state.machines[i]);
        h += '<div class="cr-stat"><div class="cr-stat-label">' + esc(u.m.id) + '</div>' +
          '<div class="cr-stat-value">' + u.uptime.toFixed(1) + '%</div>' +
          '<div class="cr-stat-sub">' + (u.downMins / 60).toFixed(1) + 'h down in 30 days</div></div>';
      }
      h += '</div>';
    }
    $('cr-u-stats').innerHTML = h;
    var el = $('cr-u-list');
    var outs = state.outages.slice().sort(function (a, b) { return a.start < b.start ? 1 : -1; });
    if (!outs.length) {
      el.innerHTML = '<p class="cr-empty">No outages logged. Clean runs stay clean.</p>';
      return;
    }
    var t = '<table class="cr-table"><thead><tr><th>Machine</th><th>Start</th><th>End</th><th>Reason</th></tr></thead><tbody>';
    for (var j = 0; j < outs.length; j++) {
      t += '<tr><td><strong>' + esc(outs[j].machine) + '</strong></td><td>' + esc(outs[j].start.replace('T', ' ')) +
        '</td><td>' + esc(outs[j].end.replace('T', ' ')) + '</td><td>' + esc(outs[j].reason || '—') + '</td></tr>';
    }
    el.innerHTML = t + '</tbody></table>';
  }
  function renderReport() {
    if (!$('cr-r-month').value) $('cr-r-month').value = thisMonth();
    var rep = reportFor($('cr-r-month').value);
    var ids = Object.keys(rep.per);
    var el = $('cr-r-out');
    if (!ids.length) {
      el.innerHTML = '<p class="cr-empty">No statement data for this month. Import statements to build the report.</p>';
      return;
    }
    var h = '<table class="cr-table"><thead><tr><th>Machine</th><th>Txns</th><th>Surcharge</th>' +
      '<th>Interchange</th><th>Fees</th><th>Net</th></tr></thead><tbody>';
    for (var i = 0; i < ids.length; i++) {
      var a = rep.per[ids[i]];
      var net = a.surcharge + a.interchange - a.fees;
      h += '<tr><td><strong>' + esc(ids[i]) + '</strong></td><td>' + a.txns + '</td><td>' + money(a.surcharge) +
        '</td><td>' + money(a.interchange) + '</td><td>' + money(a.fees) + '</td><td>' + money(net) + '</td></tr>';
    }
    var t = rep.total;
    h += '</tbody><tfoot><tr><th>Total</th><th>' + t.txns + '</th><th>' + money(t.surcharge) +
      '</th><th>' + money(t.interchange) + '</th><th>' + money(t.fees) + '</th><th>' +
      money(t.surcharge + t.interchange - t.fees) + '</th></tr></tfoot></table>';
    el.innerHTML = h;
  }

  /* ---------------- events ---------------- */
  var root = $('toolAppRoot');
  root.addEventListener('click', function (e) {
    var t = e.target;
    var tab = t.getAttribute && t.getAttribute('data-cr-tab');
    if (tab) { showTab(tab); return; }
    var dm = t.getAttribute && t.getAttribute('data-cr-delmach');
    if (dm) { removeMachine(dm); return; }
    if (t.id === 'cr-m-add') { addMachine(); return; }
    if (t.id === 'cr-c-add') { logLoad(); return; }
    if (t.id === 'cr-u-add') { logOutage(); return; }
    if (t.id === 'cr-s-demo') { loadDemo(); return; }
    if (t.id === 'cr-s-clear') { clearAll(); return; }
    if (t.id === 'cr-r-print') { printReport(); return; }
  });
  $('cr-s-file').addEventListener('change', function (e) {
    var f = e.target.files && e.target.files[0];
    if (!f) return;
    var reader = new FileReader();
    reader.onload = function () { importText(String(reader.result || '')); };
    reader.readAsText(f);
    e.target.value = '';
  });
  $('cr-r-month').addEventListener('change', function () { renderReport(); });

  (function init() {
    $('cr-c-date').value = todayStr();
    $('cr-r-month').value = thisMonth();
    var now = new Date();
    var iso = now.toISOString().slice(0, 16);
    $('cr-u-start').value = iso;
    $('cr-u-end').value = iso;
    render();
  })();
})();
